                const edgeX = 1.0 - Math.pow(lx / (width * 0.5), 2);
                const edgeZ = 1.0 - Math.pow(lz / (depth * 0.5), 2);
                const mask = Math.max(0, edgeX * edgeZ);
                const h = (perlin.noise(lx * 0.003, lz * 0.003, 3.3) * 0.5 + 0.6) * maxH * mask;
                p.setY(i, h - 1.5);
            }
            geo.computeVertexNormals();
            const mesh = new THREE.Mesh(geo, landMat);
            mesh.position.set(posX, 0, posZ);
            mesh.rotation.y = rotY;
